  const gun=new THREE.Group();gun.position.set(J.gun[0],J.gun[1],J.gun[2]);gun.rotation.x=J.grot;gun.scale.setScalar(.9);
  const gp=(w,h,d,x,y,z,rx,mt)=>{const q=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),mt||poly);q.position.set(x,y,z);if(rx)q.rotation.x=rx;q.userData.bot=b;q.castShadow=true;gun.add(q)};
  gp(.045,.1,.22,0,-.015,.11);gp(.06,.085,.34,0,0,.39);gp(.055,.07,.28,0,-.005,.7);gp(.02,.02,.26,0,.005,.96,0,steel);gp(.032,.032,.05,0,.005,1.1,0,steel);
  gp(.04,.16,.07,0,-.12,.45,-.22);gp(.04,.1,.05,0,-.09,.3,.3);gp(.022,.035,.12,0,.06,.45,0,steel);gp(.012,.045,.012,0,.05,.85,0,steel);
  up.add(gun);b.gun=gun;b.hm=new V(J.gun[0],J.gun[1]+.9,J.gun[2]+.3);b.shy=1.38;
